from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    results = []
    for group in paren_string.split():
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':  
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1
        results.append(max_depth)
    return results

from typing import List, Tuple


def sum_product(numbers: List[int]) -> Tuple[int, int]:
    sum_result = sum(numbers)
    product_result = 1
    for number in numbers:
        product_result *= number
    return (sum_result, product_result)

from typing import List, Any

def filter_integers(values: List[Any]) -> List[int]:
    return [value for value in values if isinstance(value, int)]

from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    count = {}
    # Count occurrences of each number
    for number in numbers:
        count[number] = count.get(number, 0) + 1
    # Create a new list with only numbers that occurred once
    return [number for number in numbers if count[number] == 1]

def fizz_buzz(n: int):
    count = 0
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    return count

def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing."""
    return all(l[i] <= l[i + 1] for i in range(len(l) - 1)) or all(l[i] >= l[i + 1] for i in range(len(l) - 1))

def correct_bracketing(brackets: str):
    count = 0
    for char in brackets:
        if char == '(':  
            count += 1
        elif char == ')':
            count -= 1
        if count < 0:
            return False
    return count == 0

def anti_shuffle(s):
    words = s.split(' ')
    sorted_words = []
    for word in words:
        sorted_word = ''.join(sorted(word))
        sorted_words.append(sorted_word)
    return ' '.join(sorted_words)

def next_smallest(lst):
    distinct_elements = list(set(lst))
    if len(distinct_elements) < 2:
        return None
    distinct_elements.sort()
    return distinct_elements[1]

def max_fill(grid, capacity):
    total_lowerings = 0
    for well in grid:
        water_units = sum(well)
        total_lowerings += -(-water_units // capacity)  # Equivalent to math.ceil(water_units / capacity)
    return total_lowerings

def minPath(grid, k):
    from collections import deque
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    min_path = None

    def bfs(start_row, start_col):
        queue = deque([(start_row, start_col, [grid[start_row][start_col]])])
        while queue:
            row, col, path = queue.popleft()
            if len(path) == k:
                nonlocal min_path
                if min_path is None or path < min_path:
                    min_path = path
                continue
            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < N and 0 <= new_col < N:
                    queue.append((new_row, new_col, path + [grid[new_row][new_col]]))

    for i in range(N):
        for j in range(N):
            bfs(i, j)

    return min_path

def sum_squares(lst):
    total = 0
    for i, value in enumerate(lst):
        if i % 3 == 0:
            total += value ** 2
        elif i % 4 == 0:
            total += value ** 3
        else:
            total += value
    return total

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))
    return sorted(nums, key=lambda x: (digit_sum(x), x if x >= 0 else x + float('inf')))

def x_or_y(n, x, y):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True
    return x if is_prime(n) else y

import hashlib

def string_to_md5(text):
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
